<?php get_header(); ?><main id="main" class="container page-main"><div class="content-layout"><div class="primary-content"><?php $hero=new WP_Query(array('posts_per_page'=>1,'ignore_sticky_posts'=>false,'no_found_rows'=>true));if($hero->have_posts()):$hero->the_post(); ?><section class="hero" <?php if(has_post_thumbnail())echo 'style="background-image:linear-gradient(0deg,rgba(7,8,20,.96),rgba(7,8,20,.12)),url('.esc_url(get_the_post_thumbnail_url(get_the_ID(),'gamezone-hero')).')"'; ?>><div class="hero-content"><span class="eyebrow">⚡ <?php esc_html_e('Em destaque','gamezone'); ?></span><h1><?php the_title(); ?></h1><p><?php echo esc_html(get_the_excerpt()); ?></p><a class="btn" href="<?php the_permalink(); ?>"><?php esc_html_e('Ler matéria','gamezone'); ?> →</a></div></section><?php wp_reset_postdata();else: ?><section class="hero hero-empty"><div class="hero-content"><span class="eyebrow">⚡ GameZone</span><h1><?php echo esc_html(get_theme_mod('gamezone_hero_title',__('Seu universo gamer começa aqui','gamezone'))); ?></h1><p><?php echo esc_html(get_theme_mod('gamezone_hero_description',__('Notícias, análises, lançamentos e guias em um só lugar.','gamezone'))); ?></p></div></section><?php endif; ?><section class="latest"><div class="section-heading"><h2>🎮 <?php esc_html_e('Últimos artigos','gamezone'); ?></h2><a href="<?php echo esc_url(get_post_type_archive_link('post')?:home_url('/?post_type=post')); ?>"><?php esc_html_e('Ver todos','gamezone'); ?> →</a></div><div class="post-grid"><?php $latest=new WP_Query(array('posts_per_page'=>6,'ignore_sticky_posts'=>true,'post__not_in'=>get_option('sticky_posts'),'no_found_rows'=>true));if($latest->have_posts()):while($latest->have_posts()):$latest->the_post();get_template_part('template-parts/card');endwhile;wp_reset_postdata();else: ?><div class="empty-state"><h3><?php esc_html_e('Seu portal está pronto!','gamezone'); ?></h3><p><?php esc_html_e('Crie sua primeira publicação em Posts → Adicionar novo. Defina uma imagem destacada para preencher os cartões.','gamezone'); ?></p></div><?php endif; ?></div></section></div><?php get_sidebar(); ?></div></main><?php get_footer(); ?>